package org.novasos.healthysv2.consultation;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.oauth2.jwt.*;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test") @SpringBootTest(properties={"spring.security.oauth2.resourceserver.jwt.issuer-uri=https://keycloak.example/realms/healthys","spring.security.oauth2.resourceserver.jwt.audiences=healthys-backend-apps","healthys.security.api-client-id=healthys-backend-apps","healthys.security.cors.allowed-origins=http://localhost:5173"}) @AutoConfigureMockMvc @Import({TestcontainersConfiguration.class,ConsultationApiIntegrationTests.JwtFixtures.class}) @Transactional class ConsultationApiIntegrationTests{
 static final UUID ADMIN=UUID.fromString("50000000-0000-0000-0000-000000000001");@Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;
 @Test void executesTheWholeConsultationCard()throws Exception{Graph g=graph();UUID consultation=start(g);mvc.perform(get("/api/v1/consultations/{id}/patient-summary",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.patientNumber").exists()).andExpect(jsonPath("$.activeAllergies[0]").value("Penicillin"));mvc.perform(post("/api/v1/consultations/{id}/vital-signs",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"temperature\":37.1,\"weight\":72,\"height\":180,\"systolicPressure\":120,\"diastolicPressure\":80,\"oxygenSaturation\":98,\"measuredBy\":\"%s\"}".formatted(g.professional))).andExpect(status().isCreated()).andExpect(jsonPath("$.bmi").value(22.22));mvc.perform(post("/api/v1/consultations/{id}/diagnoses",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"diagnosisCatalogId\":\"%s\",\"diagnosisType\":\"PRIMARY\"}".formatted(g.catalog))).andExpect(status().isCreated()).andExpect(jsonPath("$.catalogCode").value("I10"));mvc.perform(post("/api/v1/consultations/{id}/notes",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"authorProfessionalId\":\"%s\",\"noteType\":\"SOAP\",\"content\":\"Stable patient\"}".formatted(g.professional))).andExpect(status().isCreated());mvc.perform(post("/api/v1/consultations/{id}/observations",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"authorProfessionalId\":\"%s\",\"type\":\"GENERAL\",\"value\":\"Normal\"}".formatted(g.professional))).andExpect(status().isCreated());mvc.perform(post("/api/v1/consultations/{id}/treatments",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"description\":\"Lifestyle changes\",\"startDate\":\"%s\",\"endDate\":\"%s\"}".formatted(LocalDate.now(),LocalDate.now().plusDays(30)))).andExpect(status().isCreated());mvc.perform(post("/api/v1/consultations/{id}/follow-ups",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"recommendedDate\":\"%s\",\"instructions\":\"Blood pressure control\"}".formatted(LocalDate.now().plusDays(30)))).andExpect(status().isCreated());mvc.perform(post("/api/v1/consultations/{id}/complete",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("COMPLETED")).andExpect(jsonPath("$.completedAt").exists()).andExpect(jsonPath("$.vitalSigns.length()").value(1)).andExpect(jsonPath("$.diagnoses.length()").value(1)).andExpect(jsonPath("$.notes.length()").value(1)).andExpect(jsonPath("$.observations.length()").value(1)).andExpect(jsonPath("$.treatments.length()").value(1)).andExpect(jsonPath("$.followUps.length()").value(1));mvc.perform(post("/api/v1/consultations/{id}/notes",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"authorProfessionalId\":\"%s\",\"noteType\":\"SOAP\",\"content\":\"Too late\"}".formatted(g.professional))).andExpect(status().isUnprocessableContent()).andExpect(jsonPath("$.code").value("CONSULTATION_ALREADY_COMPLETED"));assertThatCount("select count(*) from audit.audit_log where module='CONSULTATION' and entity_id=?",consultation,8);}
 @Test void validatesVitalsAndExposesDiagnosisCatalog()throws Exception{Graph g=graph();UUID consultation=start(g);mvc.perform(post("/api/v1/consultations/{id}/vital-signs",consultation).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"temperature\":52}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_ERROR"));mvc.perform(get("/api/v1/diagnosis-catalog").header(HttpHeaders.AUTHORIZATION,"Bearer admin").param("query","hypertension")).andExpect(status().isOk()).andExpect(jsonPath("$[0].code").value("I10"));}
 private UUID start(Graph g)throws Exception{String body="{\"patientId\":\"%s\",\"professionalId\":\"%s\",\"organizationId\":\"%s\",\"type\":\"GENERAL\",\"reason\":\"Annual check-up\"}".formatted(g.patient,g.professional,g.organization);return id(mvc.perform(post("/api/v1/consultations").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("IN_PROGRESS")).andReturn().getResponse().getContentAsString());}
 private Graph graph(){UUID patientPerson=person(),professionalPerson=person(),patient=UUID.randomUUID(),professional=UUID.randomUUID(),organization=UUID.randomUUID(),catalog=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number,blood_group,rhesus) values (?,?,?,?,?)",patient,patientPerson,"PAT-"+patient,"A","POSITIVE");jdbc.update("insert into patient.allergy(id,patient_id,allergen,status) values (?,?,?,?)",UUID.randomUUID(),patient,"Penicillin","ACTIVE");jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type,status) values (?,?,?,?,?)",professional,professionalPerson,"PRO-"+professional,"DOCTOR","ACTIVE");jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",organization,"ORG-"+organization,"Hospital");jdbc.update("insert into professional.professional_assignment(id,professional_id,organization_id,start_date,status) values (?,?,?,?,?)",UUID.randomUUID(),professional,organization,LocalDate.now(),"ACTIVE");jdbc.update("insert into catalog.diagnosis_catalog(id,code,label) values (?,?,?)",catalog,"I10","Essential hypertension");return new Graph(patient,professional,organization,catalog);}private UUID person(){UUID id=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,birth_date,status) values (?,?,?,?,?,?)",id,"PER-"+id,"Jane","Doe",LocalDate.of(1990,1,1),"ACTIVE");return id;}private UUID id(String json){var m=java.util.regex.Pattern.compile("\\\"id\\\":\\\"([^\\\"]+)\\\"").matcher(json);if(!m.find())throw new IllegalArgumentException(json);return UUID.fromString(m.group(1));}private void assertThatCount(String sql,UUID id,int expected){org.assertj.core.api.Assertions.assertThat(jdbc.queryForObject(sql,Integer.class,id)).isEqualTo(expected);}record Graph(UUID patient,UUID professional,UUID organization,UUID catalog){}
 @TestConfiguration(proxyBeanMethods=false) static class JwtFixtures{@Bean JwtDecoder jwtDecoder(){return token->{Instant now=Instant.now();return Jwt.withTokenValue(token).header("alg","RS256").subject(ADMIN.toString()).issuer("https://keycloak.example/realms/healthys").audience(List.of("healthys-backend-apps")).issuedAt(now).expiresAt(now.plusSeconds(300)).claim("realm_access",Map.of("roles",List.of("PLATFORM_ADMIN"))).claim("resource_access",Map.of()).build();};}}
}
